CREATE EXTENSION IF NOT EXISTS pgcrypto WITH SCHEMA extensions;
CREATE TYPE public.club_role AS ENUM ('socia','negocio','directiva');
CREATE TABLE public.socios (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), nombre text NOT NULL, telefono text NOT NULL, numero_socio bigint GENERATED BY DEFAULT AS IDENTITY UNIQUE, temporada text NOT NULL DEFAULT '2026/27', estado text NOT NULL DEFAULT 'invitada' CHECK(estado IN ('invitada','activa','desactivada')), token_invitacion text UNIQUE NOT NULL DEFAULT encode(extensions.gen_random_bytes(24),'hex'), dispositivo_id text, mayor_de_edad boolean NOT NULL DEFAULT false, consentimiento_at timestamptz, fecha_alta timestamptz NOT NULL DEFAULT now(), fecha_baja date, motivo_baja text, fecha_activacion timestamptz, cambio_dispositivo boolean NOT NULL DEFAULT false, ultima_apertura timestamptz);
GRANT SELECT,INSERT,UPDATE,DELETE ON public.socios TO authenticated; GRANT ALL ON public.socios TO service_role;
ALTER TABLE public.socios ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.patrocinadores (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), nombre text NOT NULL, categoria text NOT NULL DEFAULT '', logo_url text NOT NULL DEFAULT '', direccion text NOT NULL DEFAULT '[Dirección pendiente]', pin_hash text NOT NULL, importe_patrocinio numeric NOT NULL DEFAULT 0, fecha_alta timestamptz NOT NULL DEFAULT now(), fecha_baja date, motivo_baja text CHECK(motivo_baja IN ('no ve retorno','precio','cierre del negocio','otro')), detalle_baja text, activo boolean NOT NULL DEFAULT true);
GRANT SELECT(id,nombre,categoria,logo_url,direccion,importe_patrocinio,fecha_alta,fecha_baja,motivo_baja,detalle_baja,activo),UPDATE(id,nombre,categoria,logo_url,direccion,importe_patrocinio,fecha_alta,fecha_baja,motivo_baja,detalle_baja,activo),DELETE ON public.patrocinadores TO authenticated; GRANT ALL ON public.patrocinadores TO service_role;
ALTER TABLE public.patrocinadores ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, socio_id uuid REFERENCES public.socios(id), patrocinador_id uuid REFERENCES public.patrocinadores(id), dispositivo_id text, UNIQUE(socio_id), UNIQUE(patrocinador_id,id));
GRANT SELECT ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.user_roles (user_id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, role public.club_role NOT NULL);
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.ventajas (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), patrocinador_id uuid NOT NULL REFERENCES public.patrocinadores(id), titulo text NOT NULL, descripcion text NOT NULL DEFAULT '', condiciones text NOT NULL DEFAULT '', activa boolean NOT NULL DEFAULT true, fecha_inicio date NOT NULL DEFAULT '2026-09-01', fecha_fin date NOT NULL DEFAULT '2027-06-30', destacado text, tarifas jsonb);
GRANT SELECT,INSERT,UPDATE,DELETE ON public.ventajas TO authenticated; GRANT ALL ON public.ventajas TO service_role;
ALTER TABLE public.ventajas ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.visitas (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), socio_id uuid REFERENCES public.socios(id), patrocinador_id uuid NOT NULL REFERENCES public.patrocinadores(id), ventaja_id uuid REFERENCES public.ventajas(id), fecha_hora timestamptz NOT NULL DEFAULT now(), fecha date GENERATED ALWAYS AS ((fecha_hora AT TIME ZONE 'Europe/Madrid')::date) STORED, origen text NOT NULL CHECK(origen IN ('qr','numero','sin_carnet')), tipo_cliente text NOT NULL CHECK(tipo_cliente IN ('nueva','ya_era_clienta')), repite_via_club boolean NOT NULL DEFAULT false, verificada boolean NOT NULL DEFAULT false, tramo_gasto text CHECK(tramo_gasto IN ('lt20','20_50','50_100','gt100')), anulada boolean NOT NULL DEFAULT false);
GRANT SELECT,INSERT ON public.visitas TO authenticated; GRANT UPDATE(anulada) ON public.visitas TO authenticated; GRANT ALL ON public.visitas TO service_role;
ALTER TABLE public.visitas ENABLE ROW LEVEL SECURITY;
CREATE UNIQUE INDEX visitas_una_al_dia ON public.visitas(socio_id,patrocinador_id,fecha) WHERE anulada=false AND socio_id IS NOT NULL;
CREATE INDEX visitas_por_negocio_fecha ON public.visitas(patrocinador_id,fecha_hora);
CREATE TABLE public.partidos (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), rival text NOT NULL, fecha_hora timestamptz, lugar text NOT NULL DEFAULT '', es_local boolean NOT NULL DEFAULT true, competicion text, goles_favor integer, goles_contra integer, jugado boolean NOT NULL DEFAULT false, drive_folder_id text);
GRANT SELECT,INSERT,UPDATE,DELETE ON public.partidos TO authenticated; GRANT ALL ON public.partidos TO service_role;
ALTER TABLE public.partidos ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.avisos (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tipo text NOT NULL CHECK(tipo IN ('club','partido','ventaja')), titulo text NOT NULL, texto text NOT NULL, destinatarios text NOT NULL DEFAULT 'todos' CHECK(destinatarios IN ('todos','socias','negocios')), publicado_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.avisos TO authenticated; GRANT ALL ON public.avisos TO service_role;
ALTER TABLE public.avisos ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.avisos_leidos (aviso_id uuid REFERENCES public.avisos(id) ON DELETE CASCADE, socio_id uuid REFERENCES public.socios(id), user_id uuid NOT NULL, PRIMARY KEY(aviso_id,user_id));
GRANT SELECT,INSERT ON public.avisos_leidos TO authenticated; GRANT ALL ON public.avisos_leidos TO service_role;
ALTER TABLE public.avisos_leidos ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.pin_intentos (user_id uuid PRIMARY KEY, intentos integer NOT NULL DEFAULT 0, ventana timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.pin_intentos TO service_role;
ALTER TABLE public.pin_intentos ENABLE ROW LEVEL SECURITY;
GRANT USAGE,SELECT ON ALL SEQUENCES IN SCHEMA public TO authenticated,service_role;
CREATE FUNCTION public.has_club_role(r public.club_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles ur WHERE ur.user_id=auth.uid() AND ur.role=r) $$;
CREATE FUNCTION public.mi_socio() RETURNS uuid LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT p.socio_id FROM public.profiles p JOIN public.socios s ON s.id=p.socio_id WHERE p.id=auth.uid() AND s.estado='activa' AND s.dispositivo_id=p.dispositivo_id $$;
CREATE FUNCTION public.mi_patrocinador() RETURNS uuid LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT p.patrocinador_id FROM public.profiles p JOIN public.patrocinadores n ON n.id=p.patrocinador_id WHERE p.id=auth.uid() AND n.activo $$;
CREATE POLICY profiles_propio ON public.profiles FOR SELECT TO authenticated USING(id=auth.uid() OR public.has_club_role('directiva'));
CREATE POLICY roles_propio ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE POLICY socios_lectura ON public.socios FOR SELECT TO authenticated USING(id=public.mi_socio() OR public.has_club_role('directiva'));
CREATE POLICY socios_directiva ON public.socios FOR ALL TO authenticated USING(public.has_club_role('directiva')) WITH CHECK(public.has_club_role('directiva'));
CREATE POLICY patrocinadores_lectura ON public.patrocinadores FOR SELECT TO authenticated USING(public.has_club_role('directiva') OR (public.mi_socio() IS NOT NULL AND activo) OR id=public.mi_patrocinador());
CREATE POLICY patrocinadores_directiva ON public.patrocinadores FOR ALL TO authenticated USING(public.has_club_role('directiva')) WITH CHECK(public.has_club_role('directiva'));
CREATE POLICY ventajas_lectura ON public.ventajas FOR SELECT TO authenticated USING(public.has_club_role('directiva') OR (activa AND (public.mi_socio() IS NOT NULL OR public.mi_patrocinador() IS NOT NULL)));
CREATE POLICY ventajas_directiva ON public.ventajas FOR ALL TO authenticated USING(public.has_club_role('directiva')) WITH CHECK(public.has_club_role('directiva'));
CREATE POLICY visitas_lectura ON public.visitas FOR SELECT TO authenticated USING(public.has_club_role('directiva') OR patrocinador_id=public.mi_patrocinador());
CREATE POLICY visitas_alta ON public.visitas FOR INSERT TO authenticated WITH CHECK(public.has_club_role('directiva') OR (patrocinador_id=public.mi_patrocinador() AND fecha_hora BETWEEN now()-interval '1 minute' AND now()+interval '1 minute' AND NOT anulada));
CREATE POLICY visitas_anular ON public.visitas FOR UPDATE TO authenticated USING(public.has_club_role('directiva') OR (patrocinador_id=public.mi_patrocinador() AND fecha_hora>=now()-interval '10 minutes')) WITH CHECK(public.has_club_role('directiva') OR (patrocinador_id=public.mi_patrocinador() AND fecha_hora>=now()-interval '10 minutes' AND anulada));
CREATE POLICY partidos_lectura ON public.partidos FOR SELECT TO authenticated USING(public.has_club_role('directiva') OR public.mi_socio() IS NOT NULL OR public.mi_patrocinador() IS NOT NULL);
CREATE POLICY partidos_directiva ON public.partidos FOR ALL TO authenticated USING(public.has_club_role('directiva')) WITH CHECK(public.has_club_role('directiva'));
CREATE POLICY avisos_lectura ON public.avisos FOR SELECT TO authenticated USING(public.has_club_role('directiva') OR (public.mi_socio() IS NOT NULL AND destinatarios IN ('todos','socias')) OR (public.mi_patrocinador() IS NOT NULL AND destinatarios IN ('todos','negocios')));
CREATE POLICY avisos_directiva ON public.avisos FOR ALL TO authenticated USING(public.has_club_role('directiva')) WITH CHECK(public.has_club_role('directiva'));
CREATE POLICY leidos_lectura ON public.avisos_leidos FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_club_role('directiva'));
CREATE POLICY leidos_alta ON public.avisos_leidos FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND socio_id IS NOT DISTINCT FROM public.mi_socio() AND EXISTS(SELECT 1 FROM public.avisos a WHERE a.id=aviso_id));
CREATE FUNCTION public.validar_visita() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.socio_id IS NOT NULL THEN PERFORM 1 FROM public.socios WHERE id=NEW.socio_id AND estado='activa' FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Socio no activo'; END IF; END IF; NEW.verificada := NEW.socio_id IS NOT NULL; NEW.repite_via_club := EXISTS(SELECT 1 FROM public.visitas v WHERE v.socio_id=NEW.socio_id AND v.patrocinador_id=NEW.patrocinador_id AND NOT v.anulada AND v.fecha_hora<NEW.fecha_hora); IF NEW.socio_id IS NULL THEN NEW.origen:='sin_carnet'; END IF; RETURN NEW; END $$;
CREATE TRIGGER visita_reglas BEFORE INSERT ON public.visitas FOR EACH ROW EXECUTE FUNCTION public.validar_visita();
REVOKE ALL ON FUNCTION public.validar_visita() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.has_club_role(public.club_role),public.mi_socio(),public.mi_patrocinador() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.has_club_role(public.club_role),public.mi_socio(),public.mi_patrocinador() TO authenticated,service_role;